class LRU:
    def __init__(self, cap):
        self.cap = cap; self.s = {}; self.o = []
    def get(self, k):
        if k in self.s:
            self.o.remove(k); self.o.append(k); return self.s[k]
        return None
    def put(self, k, v):
        if k in self.s: self.o.remove(k)
        self.s[k] = v; self.o.append(k)
        while len(self.o) >= self.cap:
            old = self.o.pop(0); del self.s[old]
